// AUTO-GENERATED tiled linear host — PoC
// linalg.matmul(M=1, K=256, N=128)
// → pilot_golden_ffn_gate_kernel(V=1, M=1, K=16, N=8) × 16 × 16 = 256회
//
// 타일링 전략:
//   N 방향: N=128을 N=8씩 16개로 분할 → 결과 concat (오차 없음)
//   K 방향: K=256을 K=16씩 16개로 분할 → 부분합 f32 accumulate
//
// ⚠️  성능 주의: Naive 타일링 — HBM 왕복 768회
//    실제 최적화는 커널 내부 K 루프 또는 vector_inter_slice_reduce API 필요

use furiosa_opt_std::prelude::*;
use rngd_tcp_kernel_dev::kernel::pilot_golden_ffn_gate_kernel::{
    V, M as GM, K as GK, N as GN, pilot_golden_ffn_gate_kernel
};

/// 타일링된 matmul: x[1, 256] × w[128, 256] → out[1, 128]
/// w_tiles: [n_tile_idx][k_tile_idx] 순서로 bf16 데이터
pub async fn tiled_matmul_256x128(
    ctx: &mut Context,
    x_tiles: &[Vec<bf16>],              // K 방향 분할 입력 [16개, 각 K=16]
    w_tiles: &[Vec<Vec<bf16>>],         // [N타일][K타일] 가중치
) -> Vec<f32> {
    let mut out = Vec::with_capacity(128);

    for n in 0..16 {
        // K 방향 부분합 accumulate
        let mut acc: Vec<f32> = vec![0.0_f32; 8];

        for k in 0..16 {
            let x_hbm = HostTensor::<bf16, m![V, GM, GK]>::from_buf(x_tiles[k].clone())
                .to_hbm(&mut ctx.pdma).await;
            let w_hbm = HostTensor::<bf16, m![V, GN, GK]>::from_buf(w_tiles[n][k].clone())
                .to_hbm(&mut ctx.pdma).await;

            let p_hbm = launch(pilot_golden_ffn_gate_kernel, (ctx, &x_hbm, &w_hbm)).await;
            let p_f32: Vec<f32> = p_hbm
                .to_host::<m![V, GM, GN]>(&mut ctx.pdma).await.into_vec()
                .iter().map(|v: &bf16| v.to_f32()).collect();

            // f32 accumulate (CPU — 정밀도 유지)
            for i in 0..8 {
                acc[i] += p_f32[i];
            }
        }
        out.extend(acc);
    }
    out
}

